def cells_of(grid, value):
    """All (i, j) positions holding the given color."""
    return [(i, j) for i in range(len(grid)) for j in range(len(grid[0])) if grid[i][j] == value]

def edge_lines(grid, value=1):
    """Rows and columns marked by pairs of value cells at opposite edges: rows with value at both col 0 and the last column, columns with value at both row 0 and the last row."""
    h, w = len(grid), len(grid[0])
    pos = cells_of(grid, value)
    rows = {i for i in range(h) if any(b == 0 for a, b in pos if a == i) and any(b == w - 1 for a, b in pos if a == i)}
    cols = {j for j in range(w) if any(a == 0 for a, b in pos if b == j) and any(a == h - 1 for a, b in pos if b == j)}
    return rows, cols

def line_cells(rows, cols, h, w):
    """Every cell of the given full rows and columns of an h x w grid."""
    return {(i, j) for i in rows for j in range(w)} | {(i, j) for j in cols for i in range(h)}

def components(grid, value=2):
    """All 4-connected components of the given color, as lists of (i, j)."""
    h, w = len(grid), len(grid[0])
    seen, comps = set(), []
    for i in range(h):
        for j in range(w):
            if grid[i][j] == value and (i, j) not in seen:
                comp, q = [(i, j)], [(i, j)]
                seen.add((i, j))
                while q:
                    a, b = q.pop()
                    for a2, b2 in ((a+1,b),(a-1,b),(a,b+1),(a,b-1)):
                        if 0 <= a2 < h and 0 <= b2 < w and grid[a2][b2] == value and (a2, b2) not in seen:
                            seen.add((a2, b2)); comp.append((a2, b2)); q.append((a2, b2))
                comps.append(comp)
    return comps

def recolor_components_touching(grid, color=2, new=1, lines=None, adjacent=True):
    """Recolor every connected component of the given color that lies on, or (optionally) shares an edge with, any of the line cells."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for comp in components(grid, color):
        hit = any((a, b) in lines for a, b in comp) or (
            adjacent and any(n in lines for a, b in comp
                             for n in ((a+1,b),(a-1,b),(a,b+1),(a,b-1))
                             if 0 <= n[0] < h and 0 <= n[1] < w))
        if hit:
            for a, b in comp:
                out[a][b] = new
    return out

def fill_lines(grid, rows, cols, value=1):
    """Every cell of the given rows and columns becomes the value."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    for i in rows:
        out[i] = [value] * w
    for j in cols:
        for i in range(h):
            out[i][j] = value
    return out
